/* копия для изменения: записи переносятся вместе с готовыми отпечатками (без повторного
   вычисления), место - с запасом вдвое, чтобы следующая запись не перестраивала таблицу */
static dm_DsTproverkau2eShablon *dm_DsTproverkau2eShablon_copy(const dm_DsTproverkau2eShablon *d) {
    dm_DsTproverkau2eShablon *r = dm_DsTproverkau2eShablon_new();
    if (d->len == 0) return r;
    int64_t cap = d->len * 2 < 8 ? 8 : d->len * 2, m = 0;
    dm_DsTproverkau2eShablon_block(r, cap);
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        r->keys[m] = dan_str_share(d->keys[e]); r->vals[m] = dt_proverkau2eShablon_share(d->vals[e]); r->hashes[m] = d->hashes[e]; r->alive[m] = true; m++;
    }
    r->n = r->len = m;
    dm_DsTproverkau2eShablon_reindex(r);
    return r;
}
static dm_DsTproverkau2eShablon *dm_DsTproverkau2eShablon_mut(dm_DsTproverkau2eShablon **pp) {
    dm_DsTproverkau2eShablon *d = *pp;
    if (d->h.rc > 1) { dm_DsTproverkau2eShablon *r = dm_DsTproverkau2eShablon_copy(d); r->h.rc = 1; d->h.rc--; *pp = r; return r; }
    return d;
}
static dan_str dm_DsTproverkau2eShablon_str(const dm_DsTproverkau2eShablon *d) {
    dan_buf b = { NULL, 0, 0 };
    dan_buf_add(&b, "{");
    bool first = true;
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        if (!first) dan_buf_add(&b, ", ");
        first = false;
        dan_buf_add(&b, dan_quote_str(d->keys[e]));
        dan_buf_add(&b, ": ");
        dan_buf_add(&b, dt_proverkau2eShablon_str(d->vals[e]));
    }
    dan_buf_add(&b, "}");
    return dan_buf_str(&b);
}
static void dm_DsTproverkau2eShablon_write(const dm_DsTproverkau2eShablon *d) { fputs(dm_DsTproverkau2eShablon_str(d), stdout); }


static bool dm_DsTproverkau2eShablon_eq(const dm_DsTproverkau2eShablon *x, const dm_DsTproverkau2eShablon *y) {
    if (x->len != y->len) return false;
    for (int64_t e = 0; e < x->n; e++) {
        if (!x->alive[e]) continue;
        int64_t f = dm_DsTproverkau2eShablon_lookup(y, x->keys[e], x->hashes[e]);
        if (f < 0) return false;
        dt_proverkau2eShablon a = x->vals[e]; dt_proverkau2eShablon b = y->vals[f];
        if (!(dt_proverkau2eShablon_eq(a, b))) return false;
    }
    return true;
}


/* ---- dictionary {стр: разбор.Узел} ---- */
struct dm_DsTrazboru2eUzel { dan_hdr h; int64_t len, n, cap, slots; dan_str *keys; dt_razboru2eUzel *vals; uint64_t *hashes; bool *alive; int64_t *index; };

static void dm_DsTrazboru2eUzel_destroy(dan_hdr *h) {
    dm_DsTrazboru2eUzel *d = (dm_DsTrazboru2eUzel *)(void *)h;
    for (int64_t e = 0; e < d->n; e++) if (d->alive[e]) { dan_str_release(d->keys[e]); dt_razboru2eUzel_release(d->vals[e]); }
    dan_free(d->hashes);
    dan_free(d);
}
static dm_DsTrazboru2eUzel *dm_DsTrazboru2eUzel_new(void) {
    dm_DsTrazboru2eUzel *d = dan_alloc(sizeof *d);
    dan_hdr_new(&d->h, dm_DsTrazboru2eUzel_destroy);
    d->len = d->n = d->cap = d->slots = 0;
    d->keys = NULL; d->vals = NULL; d->hashes = NULL; d->alive = NULL; d->index = NULL;
    return d;
}
static dm_DsTrazboru2eUzel *dm_DsTrazboru2eUzel_new_detached(void) {
    dm_DsTrazboru2eUzel *d = dan_alloc(sizeof *d);
    dan_hdr_detached(&d->h);
    d->len = d->n = d->cap = d->slots = 0;
    d->keys = NULL; d->vals = NULL; d->hashes = NULL; d->alive = NULL; d->index = NULL;
    return d;
}
static dm_DsTrazboru2eUzel *dm_DsTrazboru2eUzel_share(dm_DsTrazboru2eUzel *d) { if (d) dan_hdr_share(&d->h); return d; }
static void dm_DsTrazboru2eUzel_release(dm_DsTrazboru2eUzel *d) { if (d) dan_hdr_release(&d->h, dm_DsTrazboru2eUzel_destroy); }
static void dm_DsTrazboru2eUzel_give(dm_DsTrazboru2eUzel *d) { if (d) dan_hdr_give(&d->h, dm_DsTrazboru2eUzel_destroy); }

/* все части словаря - в одном блоке памяти (одно выделение вместо пяти): отпечатки,
   таблица поиска, ключи, значения и признаки «запись есть» на cap записей */
static void dm_DsTrazboru2eUzel_block(dm_DsTrazboru2eUzel *d, int64_t cap) {
    int64_t s = 8;
    while (s < 2 * cap) s *= 2;
    size_t c = (size_t)cap, kb = (sizeof(dan_str) * c + 7) & ~(size_t)7, vb = (sizeof(dt_razboru2eUzel) * c + 7) & ~(size_t)7;
    char *b = dan_alloc(8 * c + 8 * (size_t)s + kb + vb + c);
    d->hashes = (uint64_t *)(void *)b;
    d->index = (int64_t *)(void *)(b + 8 * c);
    d->keys = (dan_str *)(void *)(b + 8 * c + 8 * (size_t)s);
    d->vals = (dt_razboru2eUzel *)(void *)(b + 8 * c + 8 * (size_t)s + kb);
    d->alive = (bool *)(void *)(b + 8 * c + 8 * (size_t)s + kb + vb);
    d->cap = cap;
    d->slots = s;
}
static void dm_DsTrazboru2eUzel_reindex(dm_DsTrazboru2eUzel *d) {
    int64_t s = d->slots;
    for (int64_t i = 0; i < s; i++) d->index[i] = -1;
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        int64_t p = (int64_t)(d->hashes[e] & (uint64_t)(s - 1));
        while (d->index[p] >= 0) p = (p + 1) & (s - 1);
        d->index[p] = e;
    }
}
static int64_t dm_DsTrazboru2eUzel_lookup(const dm_DsTrazboru2eUzel *d, dan_str k, uint64_t h) {
    if (!d->slots) return -1;
    for (int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));; p = (p + 1) & (d->slots - 1)) {
        int64_t e = d->index[p];
        if (e < 0) return -1;
        if (d->alive[e] && d->hashes[e] == h) { dan_str a = d->keys[e], b = k; if (dan_str_eq(a, b)) return e; }
    }
}
static void dm_DsTrazboru2eUzel_grow(dm_DsTrazboru2eUzel *d) {   /* убирает удалённые записи и увеличивает таблицу */
    int64_t cap = d->len * 2 < 8 ? 8 : d->len * 2, m = 0;
    dan_str *keys = d->keys; dt_razboru2eUzel *vals = d->vals; uint64_t *hashes = d->hashes; bool *alive = d->alive;
    int64_t n = d->n;
    dm_DsTrazboru2eUzel_block(d, cap);
    for (int64_t e = 0; e < n; e++) {
        if (!alive[e]) continue;
        d->keys[m] = keys[e]; d->vals[m] = vals[e]; d->hashes[m] = hashes[e]; d->alive[m] = true; m++;
    }
    dan_free(hashes);
    d->n = m;
    dm_DsTrazboru2eUzel_reindex(d);
}
static void dm_DsTrazboru2eUzel_put(dm_DsTrazboru2eUzel *d, dan_str k, dt_razboru2eUzel v) {
    uint64_t h = dan_hash_s(k);
    int64_t e = dm_DsTrazboru2eUzel_lookup(d, k, h);
    if (e >= 0) { dt_razboru2eUzel old = d->vals[e]; d->vals[e] = dt_razboru2eUzel_share(v); dt_razboru2eUzel_release(old); (void)old; return; }
    if (d->n == d->cap) dm_DsTrazboru2eUzel_grow(d);
    e = d->n++;
    d->keys[e] = dan_str_share(k); d->vals[e] = dt_razboru2eUzel_share(v); d->hashes[e] = h; d->alive[e] = true; d->len++;
    int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));
    while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);
    d->index[p] = e;
}
/* запись в новый словарь значений, которые уже учтены (копия для задачи) */
static void dm_DsTrazboru2eUzel_put_raw(dm_DsTrazboru2eUzel *d, dan_str k, dt_razboru2eUzel v) {
    uint64_t h = dan_hash_s(k);
    if (d->n == d->cap) dm_DsTrazboru2eUzel_grow(d);
    int64_t e = d->n++;
    d->keys[e] = k; d->vals[e] = v; d->hashes[e] = h; d->alive[e] = true; d->len++;
    int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));
    while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);
    d->index[p] = e;
}
/* место значения по ключу; если ключа нет, запись создаётся со значением v (одно обращение
   вместо получить и записать) */
static dt_razboru2eUzel *dm_DsTrazboru2eUzel_slot(dm_DsTrazboru2eUzel *d, dan_str k, dt_razboru2eUzel v) {
    uint64_t h = dan_hash_s(k);
    int64_t e = dm_DsTrazboru2eUzel_lookup(d, k, h);
    if (e < 0) {
        if (d->n == d->cap) dm_DsTrazboru2eUzel_grow(d);
        e = d->n++;
        d->keys[e] = dan_str_share(k); d->vals[e] = dt_razboru2eUzel_share(v); d->hashes[e] = h; d->alive[e] = true; d->len++;
        int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));
        while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);
        d->index[p] = e;
    }
    return &d->vals[e];
}
static dm_DsTrazboru2eUzel *dm_DsTrazboru2eUzel_from(int64_t n, const dan_str *ks, const dt_razboru2eUzel *vs) {
    dm_DsTrazboru2eUzel *d = dm_DsTrazboru2eUzel_new();
    for (int64_t i = 0; i < n; i++) dm_DsTrazboru2eUzel_put(d, ks[i], vs[i]);
    return d;
}
static dt_razboru2eUzel dm_DsTrazboru2eUzel_get(const dm_DsTrazboru2eUzel *d, dan_str k, int line) {
    int64_t e = dm_DsTrazboru2eUzel_lookup(d, k, dan_hash_s(k));
    if (e < 0) dan_key_error(dan_quote_str(k), line);
    return d->vals[e];
}
