/* копия для изменения: записи переносятся вместе с готовыми отпечатками (без повторного
   вычисления), место - с запасом вдвое, чтобы следующая запись не перестраивала таблицу */
static dm_DsDsTproverkau2eSign *dm_DsDsTproverkau2eSign_copy(const dm_DsDsTproverkau2eSign *d) {
    dm_DsDsTproverkau2eSign *r = dm_DsDsTproverkau2eSign_new();
    if (d->len == 0) return r;
    int64_t cap = d->len * 2 < 8 ? 8 : d->len * 2, m = 0;
    dm_DsDsTproverkau2eSign_block(r, cap);
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        r->keys[m] = dan_str_share(d->keys[e]); r->vals[m] = dm_DsTproverkau2eSign_share(d->vals[e]); r->hashes[m] = d->hashes[e]; r->alive[m] = true; m++;
    }
    r->n = r->len = m;
    dm_DsDsTproverkau2eSign_reindex(r);
    return r;
}
static dm_DsDsTproverkau2eSign *dm_DsDsTproverkau2eSign_mut(dm_DsDsTproverkau2eSign **pp) {
    dm_DsDsTproverkau2eSign *d = *pp;
    if (d->h.rc > 1) { dm_DsDsTproverkau2eSign *r = dm_DsDsTproverkau2eSign_copy(d); r->h.rc = 1; d->h.rc--; *pp = r; return r; }
    return d;
}
static dan_str dm_DsDsTproverkau2eSign_str(const dm_DsDsTproverkau2eSign *d) {
    dan_buf b = { NULL, 0, 0 };
    dan_buf_add(&b, "{");
    bool first = true;
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        if (!first) dan_buf_add(&b, ", ");
        first = false;
        dan_buf_add(&b, dan_quote_str(d->keys[e]));
        dan_buf_add(&b, ": ");
        dan_buf_add(&b, dm_DsTproverkau2eSign_str(d->vals[e]));
    }
    dan_buf_add(&b, "}");
    return dan_buf_str(&b);
}
static void dm_DsDsTproverkau2eSign_write(const dm_DsDsTproverkau2eSign *d) { fputs(dm_DsDsTproverkau2eSign_str(d), stdout); }


static bool dm_DsDsTproverkau2eSign_eq(const dm_DsDsTproverkau2eSign *x, const dm_DsDsTproverkau2eSign *y) {
    if (x->len != y->len) return false;
    for (int64_t e = 0; e < x->n; e++) {
        if (!x->alive[e]) continue;
        int64_t f = dm_DsDsTproverkau2eSign_lookup(y, x->keys[e], x->hashes[e]);
        if (f < 0) return false;
        dm_DsTproverkau2eSign* a = x->vals[e]; dm_DsTproverkau2eSign* b = y->vals[f];
        if (!(dm_DsTproverkau2eSign_eq(a, b))) return false;
    }
    return true;
}


