static dm_DsDss *dm_DsDss_from(int64_t n, const dan_str *ks, const dm_Dss* *vs) {
    dm_DsDss *d = dm_DsDss_new();
    for (int64_t i = 0; i < n; i++) dm_DsDss_put(d, ks[i], vs[i]);
    return d;
}
static dm_Dss* dm_DsDss_get(const dm_DsDss *d, dan_str k, int line) {
    int64_t e = dm_DsDss_lookup(d, k, dan_hash_s(k));
    if (e < 0) dan_key_error(dan_quote_str(k), line);
    return d->vals[e];
}
static dm_Dss* *dm_DsDss_at(dm_DsDss *d, dan_str k, int line) {
    int64_t e = dm_DsDss_lookup(d, k, dan_hash_s(k));
    if (e < 0) dan_key_error(dan_quote_str(k), line);
    return &d->vals[e];
}
static bool dm_DsDss_contains(const dm_DsDss *d, dan_str k) { return dm_DsDss_lookup(d, k, dan_hash_s(k)) >= 0; }

static do_Dss dm_DsDss_find(const dm_DsDss *d, dan_str k) {
    int64_t e = dm_DsDss_lookup(d, k, dan_hash_s(k));
    return e < 0 ? do_Dss_none() : do_Dss_some(d->vals[e]);
}
static dm_Dss* dm_DsDss_get_or(const dm_DsDss *d, dan_str k, dm_Dss* v) {
    int64_t e = dm_DsDss_lookup(d, k, dan_hash_s(k));
    return e < 0 ? v : d->vals[e];
}
static void dm_DsDss_remove(dm_DsDss *d, dan_str k) {
    int64_t e = dm_DsDss_lookup(d, k, dan_hash_s(k));
    if (e >= 0) { d->alive[e] = false; d->len--; dan_str_release(d->keys[e]); dm_Dss_release(d->vals[e]); }
}
static dl_Ls *dm_DsDss_keys(const dm_DsDss *d) {
    dl_Ls *r = dl_Ls_from(0, NULL);
    for (int64_t e = 0; e < d->n; e++) if (d->alive[e]) dl_Ls_push(r, d->keys[e]);
    return r;
}
static dl_LDss *dm_DsDss_values(const dm_DsDss *d) {
    dl_LDss *r = dl_LDss_from(0, NULL);
    for (int64_t e = 0; e < d->n; e++) if (d->alive[e]) dl_LDss_push(r, d->vals[e]);
    return r;
}
/* копия для изменения: записи переносятся вместе с готовыми отпечатками (без повторного
   вычисления), место - с запасом вдвое, чтобы следующая запись не перестраивала таблицу */
static dm_DsDss *dm_DsDss_copy(const dm_DsDss *d) {
    dm_DsDss *r = dm_DsDss_new();
    if (d->len == 0) return r;
    int64_t cap = d->len * 2 < 8 ? 8 : d->len * 2, m = 0;
    dm_DsDss_block(r, cap);
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        r->keys[m] = dan_str_share(d->keys[e]); r->vals[m] = dm_Dss_share(d->vals[e]); r->hashes[m] = d->hashes[e]; r->alive[m] = true; m++;
    }
    r->n = r->len = m;
    dm_DsDss_reindex(r);
    return r;
}
static dm_DsDss *dm_DsDss_mut(dm_DsDss **pp) {
    dm_DsDss *d = *pp;
    if (d->h.rc > 1) { dm_DsDss *r = dm_DsDss_copy(d); r->h.rc = 1; d->h.rc--; *pp = r; return r; }
    return d;
}
static dan_str dm_DsDss_str(const dm_DsDss *d) {
    dan_buf b = { NULL, 0, 0 };
    dan_buf_add(&b, "{");
    bool first = true;
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        if (!first) dan_buf_add(&b, ", ");
        first = false;
        dan_buf_add(&b, dan_quote_str(d->keys[e]));
        dan_buf_add(&b, ": ");
        dan_buf_add(&b, dm_Dss_str(d->vals[e]));
    }
    dan_buf_add(&b, "}");
    return dan_buf_str(&b);
}
static void dm_DsDss_write(const dm_DsDss *d) { fputs(dm_DsDss_str(d), stdout); }


static bool dm_DsDss_eq(const dm_DsDss *x, const dm_DsDss *y) {
    if (x->len != y->len) return false;
    for (int64_t e = 0; e < x->n; e++) {
        if (!x->alive[e]) continue;
        int64_t f = dm_DsDss_lookup(y, x->keys[e], x->hashes[e]);
        if (f < 0) return false;
        dm_Dss* a = x->vals[e]; dm_Dss* b = y->vals[f];
        if (!(dm_Dss_eq(a, b))) return false;
    }
    return true;
}


/* ---- dictionary {стр: [разбор.Узел]} ---- */
struct dm_DsLTrazboru2eUzel { dan_hdr h; int64_t len, n, cap, slots; dan_str *keys; dl_LTrazboru2eUzel* *vals; uint64_t *hashes; bool *alive; int64_t *index; };

static void dm_DsLTrazboru2eUzel_destroy(dan_hdr *h) {
    dm_DsLTrazboru2eUzel *d = (dm_DsLTrazboru2eUzel *)(void *)h;
    for (int64_t e = 0; e < d->n; e++) if (d->alive[e]) { dan_str_release(d->keys[e]); dl_LTrazboru2eUzel_release(d->vals[e]); }
    dan_free(d->hashes);
    dan_free(d);
}
static dm_DsLTrazboru2eUzel *dm_DsLTrazboru2eUzel_new(void) {
    dm_DsLTrazboru2eUzel *d = dan_alloc(sizeof *d);
    dan_hdr_new(&d->h, dm_DsLTrazboru2eUzel_destroy);
    d->len = d->n = d->cap = d->slots = 0;
    d->keys = NULL; d->vals = NULL; d->hashes = NULL; d->alive = NULL; d->index = NULL;
    return d;
}
static dm_DsLTrazboru2eUzel *dm_DsLTrazboru2eUzel_new_detached(void) {
    dm_DsLTrazboru2eUzel *d = dan_alloc(sizeof *d);
    dan_hdr_detached(&d->h);
    d->len = d->n = d->cap = d->slots = 0;
    d->keys = NULL; d->vals = NULL; d->hashes = NULL; d->alive = NULL; d->index = NULL;
    return d;
}
static dm_DsLTrazboru2eUzel *dm_DsLTrazboru2eUzel_share(dm_DsLTrazboru2eUzel *d) { if (d) dan_hdr_share(&d->h); return d; }
static void dm_DsLTrazboru2eUzel_release(dm_DsLTrazboru2eUzel *d) { if (d) dan_hdr_release(&d->h, dm_DsLTrazboru2eUzel_destroy); }
static void dm_DsLTrazboru2eUzel_give(dm_DsLTrazboru2eUzel *d) { if (d) dan_hdr_give(&d->h, dm_DsLTrazboru2eUzel_destroy); }

/* все части словаря - в одном блоке памяти (одно выделение вместо пяти): отпечатки,
   таблица поиска, ключи, значения и признаки «запись есть» на cap записей */
static void dm_DsLTrazboru2eUzel_block(dm_DsLTrazboru2eUzel *d, int64_t cap) {
    int64_t s = 8;
    while (s < 2 * cap) s *= 2;
    size_t c = (size_t)cap, kb = (sizeof(dan_str) * c + 7) & ~(size_t)7, vb = (sizeof(dl_LTrazboru2eUzel*) * c + 7) & ~(size_t)7;
    char *b = dan_alloc(8 * c + 8 * (size_t)s + kb + vb + c);
    d->hashes = (uint64_t *)(void *)b;
    d->index = (int64_t *)(void *)(b + 8 * c);
    d->keys = (dan_str *)(void *)(b + 8 * c + 8 * (size_t)s);
    d->vals = (dl_LTrazboru2eUzel* *)(void *)(b + 8 * c + 8 * (size_t)s + kb);
    d->alive = (bool *)(void *)(b + 8 * c + 8 * (size_t)s + kb + vb);
    d->cap = cap;
    d->slots = s;
}
static void dm_DsLTrazboru2eUzel_reindex(dm_DsLTrazboru2eUzel *d) {
    int64_t s = d->slots;
    for (int64_t i = 0; i < s; i++) d->index[i] = -1;
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        int64_t p = (int64_t)(d->hashes[e] & (uint64_t)(s - 1));
        while (d->index[p] >= 0) p = (p + 1) & (s - 1);
        d->index[p] = e;
    }
}
static int64_t dm_DsLTrazboru2eUzel_lookup(const dm_DsLTrazboru2eUzel *d, dan_str k, uint64_t h) {
    if (!d->slots) return -1;
    for (int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));; p = (p + 1) & (d->slots - 1)) {
        int64_t e = d->index[p];
        if (e < 0) return -1;
        if (d->alive[e] && d->hashes[e] == h) { dan_str a = d->keys[e], b = k; if (dan_str_eq(a, b)) return e; }
    }
}
static void dm_DsLTrazboru2eUzel_grow(dm_DsLTrazboru2eUzel *d) {   /* убирает удалённые записи и увеличивает таблицу */
    int64_t cap = d->len * 2 < 8 ? 8 : d->len * 2, m = 0;
    dan_str *keys = d->keys; dl_LTrazboru2eUzel* *vals = d->vals; uint64_t *hashes = d->hashes; bool *alive = d->alive;
    int64_t n = d->n;
    dm_DsLTrazboru2eUzel_block(d, cap);
    for (int64_t e = 0; e < n; e++) {
        if (!alive[e]) continue;
        d->keys[m] = keys[e]; d->vals[m] = vals[e]; d->hashes[m] = hashes[e]; d->alive[m] = true; m++;
    }
    dan_free(hashes);
    d->n = m;
    dm_DsLTrazboru2eUzel_reindex(d);
}
static void dm_DsLTrazboru2eUzel_put(dm_DsLTrazboru2eUzel *d, dan_str k, dl_LTrazboru2eUzel* v) {
    uint64_t h = dan_hash_s(k);
    int64_t e = dm_DsLTrazboru2eUzel_lookup(d, k, h);
    if (e >= 0) { dl_LTrazboru2eUzel* old = d->vals[e]; d->vals[e] = dl_LTrazboru2eUzel_share(v); dl_LTrazboru2eUzel_release(old); (void)old; return; }
    if (d->n == d->cap) dm_DsLTrazboru2eUzel_grow(d);
    e = d->n++;
    d->keys[e] = dan_str_share(k); d->vals[e] = dl_LTrazboru2eUzel_share(v); d->hashes[e] = h; d->alive[e] = true; d->len++;
    int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));
    while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);
    d->index[p] = e;
}
/* запись в новый словарь значений, которые уже учтены (копия для задачи) */
static void dm_DsLTrazboru2eUzel_put_raw(dm_DsLTrazboru2eUzel *d, dan_str k, dl_LTrazboru2eUzel* v) {
    uint64_t h = dan_hash_s(k);
    if (d->n == d->cap) dm_DsLTrazboru2eUzel_grow(d);
    int64_t e = d->n++;
    d->keys[e] = k; d->vals[e] = v; d->hashes[e] = h; d->alive[e] = true; d->len++;
    int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));
    while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);
    d->index[p] = e;
}
/* место значения по ключу; если ключа нет, запись создаётся со значением v (одно обращение
   вместо получить и записать) */
static dl_LTrazboru2eUzel* *dm_DsLTrazboru2eUzel_slot(dm_DsLTrazboru2eUzel *d, dan_str k, dl_LTrazboru2eUzel* v) {
    uint64_t h = dan_hash_s(k);
    int64_t e = dm_DsLTrazboru2eUzel_lookup(d, k, h);
    if (e < 0) {
        if (d->n == d->cap) dm_DsLTrazboru2eUzel_grow(d);
        e = d->n++;
        d->keys[e] = dan_str_share(k); d->vals[e] = dl_LTrazboru2eUzel_share(v); d->hashes[e] = h; d->alive[e] = true; d->len++;
        int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));
        while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);
        d->index[p] = e;
    }
    return &d->vals[e];
}
